function render(){
  const page=document.body.dataset.page||"privacy";
  const stored=localStorage.getItem("mws-site-lang")||"en";
  const lang=C[page]?.[stored]?stored:"en";
  const d=C[page][lang];
  document.documentElement.lang=LANG_MAP[lang]||"en";
  document.querySelector("#legal-title").textContent=d.title;
  const eff=document.querySelector("#legal-effective"); if(eff) eff.textContent=d.effective||"";
  document.querySelector("#legal-back").innerHTML=d.back;
  document.querySelector("#legal-intro").innerHTML=d.intro;
  const box=document.querySelector("#support-box");
  if(box){box.innerHTML='<strong>'+d.box+'</strong><p><a href="mailto:mywealthsquare22@gmail.com">mywealthsquare22@gmail.com</a></p><p class="small">'+d.privacy+'</p>';}
  const root=document.querySelector("#legal-sections");
  root.innerHTML="";
  d.s.forEach(row=>{
    const h=document.createElement("h2");h.textContent=row[0];root.appendChild(h);
    const p=document.createElement("p");p.innerHTML=row[1];root.appendChild(p);
    if(Array.isArray(row[2])){const ul=document.createElement("ul");row[2].forEach(x=>{const li=document.createElement("li");li.textContent=x;ul.appendChild(li)});root.appendChild(ul);}
    if(row[3]){const p2=document.createElement("p");p2.innerHTML=row[3];root.appendChild(p2);}
  });
  document.querySelectorAll("[data-lang]").forEach(b=>b.classList.toggle("active",b.dataset.lang===lang));
}
function setLegalLang(lang){localStorage.setItem("mws-site-lang",lang);render();}
document.querySelectorAll("[data-lang]").forEach(b=>b.addEventListener("click",()=>setLegalLang(b.dataset.lang)));
render();
